w_dashboard":"view","view_claims":"none","manage_claims":"none","view_intermediaries":"none","create_intermediary_application":"none","review_intermediary_application":"none","approve_intermediary_application":"none","activate_intermediary":"none","view_customers":"view","create_customers":"edit","manage_customers":"none","view_kyc":"none","review_kyc":"none","view_employees":"none","manage_employees":"none","view_org_tree":"none","view_vehicles":"view","create_vehicles":"edit","view_policies":"view","create_policies":"edit","create_external_policies":"edit","view_policy_intakes":"view","create_policy_intakes":"none","review_policy_intakes":"edit","finalize_policy_intakes":"approve","review_policy_ocr_training":"none","approve_policy_ocr_training":"none","create_exchange_listings":"none","review_exchange_listings":"none","view_tasks":"none","manage_tasks":"none","view_accounts":"none","view_reports":"view","view_notifications":"view","manage_users":"none","manage_master_data":"none","manage_system":"none"},"accounts":{"view_dashboard":"none","view_claims":"none","manage_claims":"none","view_intermediaries":"none","create_intermediary_application":"none","review_intermediary_application":"none","approve_intermediary_application":"none","activate_intermediary":"none","view_customers":"none","create_customers":"none","manage_customers":"none","view_kyc":"none","review_kyc":"none","view_employees":"none","manage_employees":"none","view_org_tree":"none","view_vehicles":"none","create_vehicles":"none","view_policies":"none","create_policies":"none","create_external_policies":"none","view_policy_intakes":"none","create_policy_intakes":"none","review_policy_intakes":"none","finalize_policy_intakes":"none","review_policy_ocr_training":"none","approve_policy_ocr_training":"none","create_exchange_listings":"none","review_exchange_listings":"none","view_tasks":"none","manage_tasks":"none","view_accounts":"view","view_reports":"view","view_notifications":"none","manage_users":"none","manage_master_data":"none","manage_system":"none"},"agent":{"view_dashboard":"view","view_claims":"none","manage_claims":"none","view_intermediaries":"none","create_intermediary_application":"none","review_intermediary_application":"none","approve_intermediary_application":"none","activate_intermediary":"none","view_customers":"view","create_customers":"edit","manage_customers":"edit","view_kyc":"none","review_kyc":"none","view_employees":"none","manage_employees":"none","view_org_tree":"none","view_vehicles":"none","create_vehicles":"none","view_policies":"none","create_policies":"none","create_external_policies":"none","view_policy_intakes":"none","create_policy_intakes":"none","review_policy_intakes":"none","finalize_policy_intakes":"none","review_policy_ocr_training":"none","approve_policy_ocr_training":"none","create_exchange_listings":"none","review_exchange_listings":"none","view_tasks":"view","manage_tasks":"none","view_accounts":"none","view_reports":"none","view_notifications":"view","manage_users":"none","manage_master_data":"none","manage_system":"none"},"customer":{"view_dashboard":"none","view_claims":"none","manage_claims":"none","view_intermediaries":"none","create_intermediary_application":"none","review_intermediary_application":"none","approve_intermediary_application":"none","activate_intermediary":"none","view_customers":"none","create_customers":"none","manage_customers":"none","view_kyc":"none","review_kyc":"none","view_employees":"none","manage_employees":"none","view_org_tree":"none","view_vehicles":"none","create_vehicles":"none","view_policies":"none","create_policies":"none","create_external_policies":"none","view_policy_intakes":"none","create_policy_intakes":"none","review_policy_intakes":"none","finalize_policy_intakes":"none","review_policy_ocr_training":"none","approve_policy_ocr_training":"none","create_exchange_listings":"none","review_exchange_listings":"none","view_tasks":"none","manage_tasks":"none","view_accounts":"none","view_reports":"none","view_notifications":"none","manage_users":"none","manage_master_data":"none","manage_system":"none"},"intermediary":{"view_dashboard":"none","view_claims":"none","manage_claims":"none","view_intermediaries":"none","create_intermediary_application":"none","review_intermediary_application":"none","approve_intermediary_application":"none","activate_intermediary":"none","view_customers":"none","create_customers":"none","manage_customers":"none","view_kyc":"none","review_kyc":"none","view_employees":"none","manage_employees":"none","view_org_tree":"none","view_vehicles":"none","create_vehicles":"none","view_policies":"none","create_policies":"none","create_external_policies":"none","view_policy_intakes":"none","create_policy_intakes":"none","review_policy_intakes":"none","finalize_policy_intakes":"none","review_policy_ocr_training":"none","approve_policy_ocr_training":"none","create_exchange_listings":"none","review_exchange_listings":"none","view_tasks":"none","manage_tasks":"none","view_accounts":"none","view_reports":"none","view_notifications":"none","manage_users":"none","manage_master_data":"none","manage_system":"none"}}'::jsonb;
  v_partner_defaults jsonb := '{"view_dashboard":"view","view_reports":"view","view_customers":"view","create_customers":"edit","view_policies":"view","view_claims":"view","view_policy_intakes":"view","create_policy_intakes":"edit","view_notifications":"view"}'::jsonb;
  v_bo_ceiling jsonb := '{"view_dashboard":"view","view_customers":"view","create_customers":"edit","view_vehicles":"view","create_vehicles":"edit","view_policies":"view","create_policies":"edit","create_external_policies":"edit","view_policy_intakes":"view","review_policy_intakes":"edit","finalize_policy_intakes":"approve","view_reports":"view","view_notifications":"view"}'::jsonb;
  v_bo_emp_ceiling jsonb := '{"view_intermediaries":"view","create_intermediary_application":"edit","review_intermediary_application":"edit","approve_intermediary_application":"approve","activate_intermediary":"approve"}'::jsonb;
  v_life_ceiling jsonb := '{"view_policies":"view","view_intermediaries":"view"}'::jsonb;
  v_role text;
  v_cap text;
  v_level text;
  v_ceiling text;
  v_employee_override text;
  v_role_override text;
  v_rank integer;
  v_max_rank integer;
  v_commercial boolean := false;
begin
  if v_uid is null then return null; end if;
  v_identity := public.partner_app_current_identity();
  if v_identity is null or v_identity->>'auth_user_id' is distinct from v_uid::text then return null; end if;
  v_scope := public.partner_app_commercial_scope();
  if v_scope is null or v_scope->>'actor_kind' is distinct from v_identity->>'actor_kind' then return null; end if;
  if v_identity->>'actor_kind' = 'intermediary' then
    return jsonb_build_object('actor_kind','intermediary','capabilities',v_partner_defaults,'can_view_insurer_commercials',false);
  end if;
  if v_identity->>'actor_kind' <> 'employee' or v_identity->>'profile_id' is distinct from v_uid::text then return null; end if;
  select * into v_profile from public.profiles where id = v_uid;
  if not found or not coalesce(v_profile.is_active,false) or v_profile.employee_id is null
     or v_profile.role::text is distinct from v_identity->>'role' then return null; end if;
  select employment_status into v_employee_state from public.employees where id = v_profile.employee_id;
  if v_employee_state is distinct from 'active' then return null; end if;
  v_role := v_profile.role::text;
  if not (v_defaults ? v_role) or v_role in ('customer','intermediary') then return null; end if;
  if v_role = 'accounts' then
    return jsonb_build_object('actor_kind','employee','capabilities',jsonb_build_object('view_accounts','view'),'can_view_insurer_commercials',true);
  end if;

  for v_cap in select jsonb_object_keys(v_defaults->v_role) loop
    v_level := v_defaults->v_role->>v_cap;
    -- Protected IT roles ignore overrides, preserving the current web engine.
    if v_role not in ('it_super_user','it_user') then
      select access_level into v_employee_override
      from public.employee_permission_overrides
      where profile_id = v_uid and capability = v_cap
        and (expires_at is null or expires_at > now())
      limit 1;
      if v_employee_override is not null and v_employee_override <> 'inherit' then
        v_level := v_employee_override;
        if v_role='backoffice_executive' then
          v_ceiling := coalesce(v_bo_emp_ceiling->>v_cap, v_bo_ceiling->>v_cap,'none');
        elsif v_role='operations_head_life' then
          v_ceiling := coalesce(v_life_ceiling->>v_cap,'none');
        else v_ceiling := 'approve'; end if;
      else
        select access_level into v_role_override from public.role_permission_overrides
        where role = v_role and capability = v_cap limit 1;
        v_level := coalesce(v_role_override,v_level);
        if v_role='backoffice_executive' then v_ceiling := coalesce(v_bo_ceiling->>v_cap,'none');
        elsif v_role='operations_head_life' then v_ceiling := coalesce(v_life_ceiling->>v_cap,'none');
        else v_ceiling := 'approve'; end if;
      end if;
      v_rank := case v_level when 'view' then 1 when 'edit' then 2 when 'approve' then 3 else 0 end;
      v_max_rank := case v_ceiling when 'view' then 1 when 'edit' then 2 when 'approve' then 3 else 0 end;
      if v_rank > v_max_rank then v_level := v_ceiling; end if;
    end if;
    if v_level not in ('none','view','edit','approve') then
      raise exception 'invalid_permission_override' using errcode = 'P0001';
    end if;
    v_caps := v_caps || jsonb_build_object(v_cap,v_level);
    v_employee_override := null;
    v_role_override := null;
    v_ceiling := null;
  end loop;
  v_commercial := (v_uid = any(array['87e3985c-3488-401b-a3bc-5e270c74c759'::uuid,'21a8b85f-5051-4fec-8b29-3960163b6d1f'::uuid,'dd3a036f-2cca-4a1e-b639-21fc1cc807ef'::uuid,'1b7cb2bb-e9a3-4713-ab42-56758dab10c9'::uuid,'8c4ec4a2-d940-4394-b484-698e9ab70a69'::uuid,'f634d48a-e075-4dbd-849c-3e17974f3f94'::uuid]));
  return jsonb_build_object('actor_kind','employee','capabilities',v_caps,'can_view_insurer_commercials',v_commercial);
end
